class InlinedAnnotationDrawingStrategy {
    // This static method is refactored away in the target code base, but exists at the point of transformation
    public static StyleRange updateStyle(LineContentAnnotation annotation, StyleRange style) {
        int width = annotation.getWidth();
        int charWidth = annotation.getRedrawnCharacterWidth();
        if (width == 0 || charWidth == 0) {
            return null;
        }
        int fullWidth = width + charWidth;
        if (style == null) {
            style = new StyleRange();
            Position position = annotation.getPosition();
            style.start = position.getOffset();
            style.length = 1;
        }
        GlyphMetrics metrics = style.metrics;
        if (!annotation.isMarkedDeleted()) {
            if (metrics == null) {
                metrics = new GlyphMetrics(0, 0, fullWidth);
            } else {
                metrics = new GlyphMetrics(0, 0, fullWidth);
            }
        } else {
            metrics = null;
        }
        style.metrics = metrics;
        return style;
    }

    public void someMethod() {
        // Dummy LineContentAnnotation and StyleRange for the example
        LineContentAnnotation ann = new LineContentAnnotation(new Position(0, 10)); 
        StyleRange existingStyle = new StyleRange();
        // This is the target line for transformation
        StyleRange newStyle = InlinedAnnotationDrawingStrategy.updateStyle(ann, existingStyle);
        System.out.println(newStyle);
    }
}

